import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    is_url = webpage_url.startswith("http://") or webpage_url.startswith("https://")
    content = None
    if is_url:
        try:
            response = requests.get(webpage_url)
            response.raise_for_status()
            content = response.text
        except requests.RequestException as e:
            raise requests.RequestException(f"Error fetching URL {webpage_url}: {e}")
    else:
        try:
            with open(webpage_url, "r", encoding="utf-8") as f:
                content = f.read()
        except OSError as e:
            content = ""
    if not content:
        return 0
    tree = html.fromstring(content)
    tables = tree.xpath("//table")
    if not tables:
        return 0
    table = tables[0]
    header_cells = table.xpath(".//tr[1]/th")
    headers = [cell.text_content().strip() for cell in header_cells] if header_cells else []
    rows = []
    data_rows = table.xpath(".//tr")
    for i, row in enumerate(data_rows):
        if i == 0 and header_cells:
            continue
        cells = row.xpath(".//td")
        if not cells:
            continue
        rows.append([cell.text_content().strip() for cell in cells])
    if not rows:
        return 0
    if headers and len(headers) == len(rows[0]):
        df = pd.DataFrame(rows, columns=headers)
    else:
        df = pd.DataFrame(rows)
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Error working with database {database_name}: {e}")
    return len(df)
