        def get(self):
            try:
                response = requests.get(api_url)
                response.raise_for_status()
            except requests.ConnectionError as e:
                return {"error": f"Connection error while accessing external API: {e}"}, 502
            except requests.HTTPError as e:
                return {"error": f"HTTP error from external API: {e}"}, response.status_code if "response" in locals() else 502
            except requests.RequestException as e:
                return {"error": f"Error while requesting external API: {e}"}, 502
            try:
                data = response.json()
            except ValueError:
                return {"error": "Invalid JSON received from external API"}, 502
            return jsonify(data)
    api.add_resource(ExternalAPIResource, "/data")
    return app
